  id: "JAH-FUND-000001",
  title: "GoFundMe",
  kind: "fundraising platform",
  developer: "GoFundMe",
  platforms: "any modern web browser, Android, iOS and iPadOS",
  license: "Freemium"
};
function demo() {
  console.log("=== " + record.title + " ===");
